window.skillUpFocusedPrimarySuccessionQuestions=dedicated([["Primary succession begins where:",["developed soil is absent or minimal","a mature forest already exists","cultivated soil is intact","a seed bank is always abundant"],0,"Primary succession begins on newly exposed or soil-free substrate."],["A classic substrate for primary succession is:",["bare rock","fertile topsoil","abandoned farmland","disturbed grassland"],0,"Bare rock lacks developed soil."],["Lichens commonly act as pioneers on:",["bare rock","deep forest soil","crop fields","mature wetlands"],0,"Lichens can colonize exposed rock."],["Weathering during primary succession helps produce:",["mineral particles for soil","DNA","ATP","chlorophyll"],0,"Weathering contributes mineral material to developing soil."],["Primary succession is generally slow because:",["soil must develop","sunlight is absent","oxygen is absent","decomposers cannot exist"],0,"Soil formation takes time."],["A newly exposed lava surface may undergo:",["primary succession","secondary succession","population growth","genetic drift"],0,"Fresh lava may lack developed soil."],["Pioneer organisms are the:",["first colonizers","final community","top predators","late-successional trees"],0,"Pioneers establish first."],["Organic matter accumulation during primary succession promotes:",["soil development","rock removal","DNA replication","predator extinction"],0,"Organic residues contribute to soil."],["A key initial limitation on bare rock is:",["lack of developed soil","excessive humus","high seed-bank density","mature vegetation"],0,"Bare rock has little developed soil."],["Pioneer lichens can facilitate succession by:",["weathering rock and adding organic matter","removing all minerals","preventing microbial activity","eliminating water"],0,"They help modify the substrate."],["Primary succession may occur after:",["glacier retreat exposes bare rock","a crop field is abandoned","a forest is logged but soil remains","a grassland burns with soil intact"],0,"Glacier retreat can expose soil-free substrate."],["The first stages of primary succession often have:",["low biomass and few species","high biomass and many mature trees","only consumers","no producers"],0,"Initial communities are sparse."],["As primary succession progresses, soil depth generally:",["increases","disappears","remains zero","becomes unrelated to organisms"],0,"Soil develops and accumulates."],["Humus formation during succession generally:",["improves soil organic matter","removes all nutrients","prevents decomposition","destroys soil"],0,"Humus is organic matter in soil."],["Primary succession differs from secondary succession mainly because:",["primary succession starts without developed soil","primary succession always occurs in water","secondary succession has no organisms","secondary succession never follows disturbance"],0,"Initial soil condition is the key distinction."],["Rock weathering supplies developing soil with:",["minerals","genes","hormones","enzymes"],0,"Weathering releases mineral material."],["Pioneer species must often tolerate:",["harsh initial conditions","mature forest shade only","deep fertile soil only","high competition from mature trees"],0,"Initial substrates can be harsh."],["As soil develops, colonization can become:",["possible for more species","impossible for plants","restricted to lichens","independent of nutrients"],0,"Improved substrate supports more species."],["Primary succession can eventually produce:",["a complex established community","only bare rock","only lichens permanently","no decomposers"],0,"Succession proceeds toward more developed communities."],["Microorganisms contribute to primary succession through:",["decomposition and nutrient cycling","eliminating soil","preventing colonization","stopping weathering"],0,"Microbes contribute to nutrient cycling."],["A rock-based succession is often called a:",["lithosere","hydrosere","food web","gene pool"],0,"Lithosere refers to succession beginning on rock."],["The accumulation of dead organic matter can:",["increase soil fertility","remove all nutrients","prevent plant establishment","stop decomposition"],0,"Organic matter can improve nutrient availability."],["Primary succession demonstrates:",["ecosystem development from a new substrate","allele segregation","DNA translation","protein folding"],0,"It describes community development."],["A soil-free mineral surface is evidence for:",["primary succession potential","secondary succession only","population explosion","climax stability"],0,"Lack of developed soil indicates primary succession."],["Pioneer plants can alter the environment by:",["adding organic matter and changing substrate conditions","removing all water","stopping weathering","eliminating microbes"],0,"Pioneers modify conditions."],["Primary succession can change:",["soil depth, biomass and species composition","only chromosome number","only DNA sequence","only body size"],0,"Multiple ecosystem properties change."],["The development of soil allows:",["greater plant establishment","permanent bare rock","loss of decomposers","loss of nutrient cycling"],0,"Soil supports more vegetation."],["In primary succession, nutrients initially are often:",["limited","unlimited","irrelevant","only atmospheric"],0,"New substrates contain limited organic nutrients."],["A mature ecosystem after primary succession contains:",["producers, consumers and decomposers","only pioneers","only decomposers","only abiotic components"],0,"Mature ecosystems contain multiple trophic groups."],["The main ecological significance of primary succession is:",["recovery and development from initially sparse substrate","inheritance of alleles","protein synthesis","cell division"],0,"It explains ecosystem establishment."]]);

window.skillUpFocusedSecondarySuccessionQuestions=dedicated([["Secondary succession begins when:",["soil remains after disturbance","bare rock has never been colonized","no organic matter remains","a new planet forms"],0,"Existing soil distinguishes secondary succession."],["A burned grassland with soil intact undergoes:",["secondary succession","primary succession","genetic drift","no succession"],0,"Soil remains after the disturbance."],["Secondary succession is usually faster because:",["soil and biological legacies remain","sunlight is stronger","there are no competitors","decomposition stops"],0,"Existing soil, seeds and microbes accelerate recovery."],["An abandoned crop field may undergo:",["secondary succession","primary succession","no ecological change","mutation"],0,"Agricultural soil remains after abandonment."],["A forest recovering after a cyclone is an example of:",["secondary succession","primary succession","genetic drift","artificial selection"],0,"Soil generally remains after such disturbance."],["A seed bank can accelerate:",["secondary succession","primary rock formation","DNA replication","extinction"],0,"Stored seeds provide propagules."],["Surviving roots after disturbance can promote:",["rapid regrowth","soil loss","primary succession","nutrient elimination"],0,"Roots can regenerate vegetation."],["Secondary succession commonly starts with:",["herbs and grasses","only climax trees","only lichens","no producers"],0,"Fast-growing plants often recolonize first."],["Secondary succession may follow:",["fire that leaves soil","fresh lava without soil","newly exposed bedrock","glacial rock exposure"],0,"Disturbance with soil remaining produces secondary succession."],["The key distinction from primary succession is:",["initial soil presence","sunlight availability","oxygen availability","presence of producers"],0,"Secondary succession begins with existing soil."],["Surviving microorganisms after disturbance help maintain:",["nutrient cycling","bare rock","genetic isolation","absence of decomposition"],0,"Microbes continue decomposition and nutrient cycling."],["Secondary succession can include stages of:",["herbs, shrubs and trees","only algae","only lichens","only bacteria"],0,"Vegetation often develops through these stages."],["Disturbance severity affects succession by changing:",["how much soil and biological material remains","the genetic code of every species","the existence of sunlight","water's molecular formula"],0,"More severe disturbance can remove more biological legacy."],["Abandoned farmland commonly retains:",["soil and seed banks","bare rock only","no nutrients","no microorganisms"],0,"These remnants support recovery."],["Secondary succession demonstrates:",["ecosystem recovery after disturbance","DNA replication","allele segregation","translation"],0,"It describes community recovery."],["Existing soil can provide:",["nutrients and microbial habitat","only oxygen","only sunlight","only DNA"],0,"Soil contains nutrients and organisms."],["Secondary succession may be slowed when:",["soil is severely removed","seed banks remain","roots survive","microbes remain"],0,"Loss of soil and biological legacies slows recovery."],["A logged forest can undergo:",["secondary succession","primary succession necessarily","no succession","genetic drift"],0,"Logging can leave soil intact."],["Flood disturbance followed by regrowth on intact soil is:",["secondary succession","primary succession","mutation","extinction"],0,"Existing soil allows secondary recovery."],["Secondary succession may involve competition because:",["new species compete for resources","resources are unlimited","all species occupy identical niches","competition occurs only in genes"],0,"Competition influences community assembly."],["Dispersal contributes to secondary succession by:",["bringing propagules to disturbed sites","removing soil","stopping germination","eliminating producers"],0,"Seeds and other propagules recolonize sites."],["A forest fire that leaves soil generally causes:",["secondary succession","primary succession","no succession","only genetic change"],0,"Soil remains after many fires."],["The first colonists after disturbance are often:",["fast-growing herbs","late climax trees only","top predators","large mammals only"],0,"Early colonists often grow rapidly."],["Later secondary stages may include:",["shrubs and trees","bare rock","only lichens","no producers"],0,"Woody plants often establish later."],["Secondary succession can restore:",["biomass and community structure","only DNA","only chromosome number","only body size"],0,"Community properties recover over time."],["Soil organisms surviving disturbance can:",["speed nutrient cycling","prevent plant growth","remove all carbon","stop decomposition"],0,"Surviving decomposers support recovery."],["Secondary succession is associated with:",["previous occupation of the site","complete absence of soil","fresh lava","newly exposed rock"],0,"The site was previously occupied."],["A ploughed field left uncultivated can develop through:",["secondary succession","primary succession","no succession","genetic drift"],0,"The soil remains after cultivation."],["Secondary succession can be viewed as:",["community reassembly after disturbance","DNA repair","cell division","protein synthesis"],0,"It is ecological reassembly."],["The presence of soil makes recovery:",["generally faster than primary succession","impossible","independent of organisms","always instantaneous"],0,"Existing soil reduces the initial barrier."]]);

